properties.query:
let windowSize = 2h;

// S54: Webshell Upload
let S54 =
    UAVWebAccess_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'webshell_upload'
    | extend Stage = 'S54', Operator = tostring(Operator)
    | where isnotempty(Operator)
    | project TimeGenerated, Stage, Operator;

// S56: Container Escape
let S56 =
    UAVContainerOps_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'escape_detected'
    | extend Stage = 'S56', Operator = tostring(Operator)
    | where isnotempty(Operator)
    | project TimeGenerated, Stage, Operator;

// S36: Mission Self-Approval
let S36 =
    UAVMission_CL
    | where TimeGenerated > ago(windowSize)
    | where Planner == Approver and Operator == Planner
    | extend Stage = 'S36', Operator = tostring(Operator)
    | where isnotempty(Operator)
    | project TimeGenerated, Stage, Operator;

// S3: Weapon Arm
let S3 =
    UAVWeapon_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType in ('arm','fire')
    | extend Stage = 'S3', Operator = tostring(Operator)
    | where isnotempty(Operator)
    | project TimeGenerated, Stage, Operator;

union S54, S56, S36, S3
| summarize StagesSeen = make_set(Stage), StageCount = dcount(Stage), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by Operator
| where StageCount >= 3
| extend CampaignType = "C15_웹셸_컨테이너escape_임무자기승인_무장"
| extend StepSummary = strcat("Stages=", tostring(StagesSeen), " | First=", tostring(FirstSeen), " | Last=", tostring(LastSeen))
| extend Severity = "High"
| project FirstSeen, LastSeen, Operator, StagesSeen, StageCount, CampaignType, StepSummary, Severity
